//! Staged, all-or-nothing application of generated file changes.
//!
//! A [`GenerationTransaction`] takes a set of proposed writes and deletions,
//! checks each against the confined output root and the last accepted
//! manifest, stages the new content under `.sayn/staging/<run-id>`, lets the
//! caller validate the complete candidate tree, and only then replaces files
//! in the real output. If any step fails the previous output is left, or put
//! back, exactly as it was.

use crate::manifest::Manifest;
use sayn_security::confine_path;
use serde::Serialize;
use std::collections::{HashMap, HashSet};
use std::fs;
use std::io;
use std::path::{Component, Path, PathBuf};
use thiserror::Error;
use walkdir::WalkDir;

/// Directory names that are never copied into a candidate tree and never
/// accepted as write targets.
const UNMANAGED_DIRS: [&str; 3] = ["node_modules", ".next", ".git"];

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum StagedChange {
    Write { path: String, content: Vec<u8> },
    Delete { path: String },
}

impl StagedChange {
    fn path(&self) -> &str {
        match self {
            Self::Write { path, .. } | Self::Delete { path } => path,
        }
    }
}

#[derive(Error, Debug)]
pub enum TransactionError {
    #[error("run id '{0}' cannot be used as a staging directory name")]
    InvalidRunId(String),

    #[error("'{0}' is not a permitted location inside the generated project")]
    UnsafePath(String),

    #[error("more than one change targets '{0}'")]
    DuplicateTarget(String),

    #[error(
        "generated files were edited by hand or are not managed by Sayn, and would be overwritten: {}",
        paths.join(", ")
    )]
    ManualEditConflict { paths: Vec<String> },

    #[error("'{0}' was not generated by Sayn, so it will not be deleted")]
    UnmanagedDelete(String),

    #[error("'{0}' is a directory, not a file")]
    NotAFile(String),

    #[error("'{0}' changed on disk while the run was in progress")]
    ChangedDuringRun(String),

    #[error("the candidate application failed validation: {0}")]
    Validation(String),

    #[error("the generated files could not be applied ({reason}); previous output {}",
        if *rolled_back { "was restored" } else { "could NOT be fully restored; see the staging journal" })]
    CommitFailed { reason: String, rolled_back: bool },

    #[error("filesystem error: {0}")]
    Io(#[from] io::Error),
}

/// What a successful commit changed.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CommitReport {
    pub written: Vec<String>,
    pub deleted: Vec<String>,
    /// Digests of every managed generated file after the commit, keyed like
    /// [`Manifest::generated_hashes`].
    pub generated_hashes: HashMap<String, String>,
}

enum Action {
    Write { staged: PathBuf, digest: String },
    Delete,
}

struct Entry {
    /// Normalized `a/b/c` path relative to the output root.
    rel: String,
    /// Manifest key for this file.
    key: String,
    target: PathBuf,
    action: Action,
    /// Digest of the file on disk when it was staged; `None` if absent.
    observed: Option<String>,
}

/// Bookkeeping for one change already applied to the real output.
struct Applied {
    target: PathBuf,
    backup: Option<PathBuf>,
    created_dirs: Vec<PathBuf>,
}

#[derive(Serialize)]
struct Journal<'a> {
    run_id: &'a str,
    state: &'a str,
    updated_at: String,
    reason: Option<&'a str>,
    changes: Vec<JournalChange<'a>>,
}

#[derive(Serialize)]
struct JournalChange<'a> {
    path: &'a str,
    action: &'a str,
}

pub struct GenerationTransaction {
    project_root: PathBuf,
    output_root: PathBuf,
    run_id: String,
    staging_dir: PathBuf,
    known_hashes: HashMap<String, String>,
    entries: Vec<Entry>,
    seen: HashSet<String>,
}

impl GenerationTransaction {
    /// Where a run's staging area lives.
    pub fn staging_dir_for(project_root: &Path, run_id: &str) -> PathBuf {
        project_root.join(".sayn/staging").join(run_id)
    }

    /// Open a transaction. `previous` is the last accepted manifest; files it
    /// does not record are treated as not managed by Sayn.
    pub fn begin(
        project_root: &Path,
        output_root: &Path,
        run_id: &str,
        previous: Option<&Manifest>,
    ) -> Result<Self, TransactionError> {
        let run_id_is_safe = !run_id.is_empty()
            && run_id.len() <= 128
            && run_id
                .chars()
                .all(|ch| ch.is_ascii_alphanumeric() || ch == '-' || ch == '_');
        if !run_id_is_safe {
            return Err(TransactionError::InvalidRunId(run_id.to_string()));
        }

        let staging_dir = Self::staging_dir_for(project_root, run_id);
        if staging_dir.exists() {
            fs::remove_dir_all(&staging_dir)?;
        }
        fs::create_dir_all(staging_dir.join("files"))?;

        let transaction = Self {
            project_root: project_root.to_path_buf(),
            output_root: output_root.to_path_buf(),
            run_id: run_id.to_string(),
            staging_dir,
            known_hashes: previous
                .map(|manifest| manifest.generated_hashes.clone())
                .unwrap_or_default(),
            entries: Vec::new(),
            seen: HashSet::new(),
        };
        transaction.write_journal("staging", None)?;
        Ok(transaction)
    }

    /// Check and stage a batch of changes. Either the whole batch is staged or
    /// none of it is; the real output is never touched here.
    pub fn stage(&mut self, changes: &[StagedChange]) -> Result<(), TransactionError> {
        let mut pending = Vec::new();
        let mut batch_seen = HashSet::new();
        let mut conflicts = Vec::new();

        for change in changes {
            let raw = change.path();
            let target = confine_path(&self.output_root, Path::new(raw.trim()))
                .map_err(|_| TransactionError::UnsafePath(raw.to_string()))?;
            let rel = self.relative_name(&target, raw)?;

            let identity = rel.to_lowercase();
            if self.seen.contains(&identity) || !batch_seen.insert(identity) {
                return Err(TransactionError::DuplicateTarget(raw.to_string()));
            }

            let key = self.manifest_key(&target, &rel);
            let observed = match fs::symlink_metadata(&target) {
                Ok(metadata) if metadata.is_dir() => {
                    return Err(TransactionError::NotAFile(rel));
                }
                Ok(_) => Some(Manifest::compute_file_hash(&target)?),
                Err(error) if error.kind() == io::ErrorKind::NotFound => None,
                Err(error) => return Err(error.into()),
            };
            let known = self.known_hashes.get(&key);

            match change {
                StagedChange::Write { content, .. } => {
                    let digest = Manifest::compute_sha256(content);
                    let untouched = match &observed {
                        None => true,
                        Some(current) => known == Some(current) || *current == digest,
                    };
                    if !untouched {
                        conflicts.push(rel);
                        continue;
                    }
                    pending.push((rel, key, target, observed, Some((content, digest))));
                }
                StagedChange::Delete { .. } => match (&observed, known) {
                    // Already absent: nothing to do.
                    (None, _) => {}
                    (Some(_), None) => return Err(TransactionError::UnmanagedDelete(rel)),
                    (Some(current), Some(recorded)) if current == recorded => {
                        pending.push((rel, key, target, observed, None));
                    }
                    (Some(_), Some(_)) => conflicts.push(rel),
                },
            }
        }

        if !conflicts.is_empty() {
            return Err(TransactionError::ManualEditConflict { paths: conflicts });
        }

        for (rel, key, target, observed, write) in pending {
            let action = match write {
                Some((content, digest)) => {
                    let staged = self.staging_dir.join("files").join(&rel);
                    if let Some(parent) = staged.parent() {
                        fs::create_dir_all(parent)?;
                    }
                    fs::write(&staged, content)?;
                    Action::Write { staged, digest }
                }
                None => Action::Delete,
            };
            self.seen.insert(rel.to_lowercase());
            self.entries.push(Entry {
                rel,
                key,
                target,
                action,
                observed,
            });
        }
        self.write_journal("staged", None)?;
        Ok(())
    }

    /// Build the complete candidate tree (current output plus staged changes)
    /// and run `check` on it. The real output is not modified.
    pub fn validate<F>(&self, check: F) -> Result<(), TransactionError>
    where
        F: FnOnce(&Path) -> Result<(), String>,
    {
        let candidate = self.build_candidate_tree()?;
        let outcome = check(&candidate);
        let _ = fs::remove_dir_all(&candidate);
        outcome.map_err(TransactionError::Validation)
    }

    /// Replace files in the real output. On any failure every change already
    /// applied is undone and the staging journal records what happened.
    pub fn commit(self) -> Result<CommitReport, TransactionError> {
        // Nothing may have moved underneath us since staging.
        for entry in &self.entries {
            let current = match fs::symlink_metadata(&entry.target) {
                Ok(metadata) if metadata.is_file() => {
                    Some(Manifest::compute_file_hash(&entry.target)?)
                }
                Ok(_) => {
                    return self
                        .fail_untouched(TransactionError::ChangedDuringRun(entry.rel.clone()));
                }
                Err(error) if error.kind() == io::ErrorKind::NotFound => None,
                Err(error) if error.kind() == io::ErrorKind::NotADirectory => {
                    return self
                        .fail_untouched(TransactionError::ChangedDuringRun(entry.rel.clone()));
                }
                Err(error) => return Err(error.into()),
            };
            if current != entry.observed {
                return self.fail_untouched(TransactionError::ChangedDuringRun(entry.rel.clone()));
            }
        }

        self.write_journal("committing", None)?;
        let backup_root = self.staging_dir.join("backup");
        let mut applied: Vec<Applied> = Vec::new();

        for entry in &self.entries {
            if let Err(error) = self.apply_entry(entry, &backup_root, &mut applied) {
                let reason = format!("{}: {}", entry.rel, error);
                let rolled_back = Self::roll_back(&applied);
                let state = if rolled_back {
                    "rolled_back"
                } else {
                    "rollback_incomplete"
                };
                let _ = self.write_journal(state, Some(&reason));
                return Err(TransactionError::CommitFailed {
                    reason,
                    rolled_back,
                });
            }
        }

        let mut generated_hashes = self.known_hashes.clone();
        let mut written = Vec::new();
        let mut deleted = Vec::new();
        for entry in &self.entries {
            match &entry.action {
                Action::Write { digest, .. } => {
                    generated_hashes.insert(entry.key.clone(), digest.clone());
                    written.push(entry.rel.clone());
                }
                Action::Delete => {
                    generated_hashes.remove(&entry.key);
                    deleted.push(entry.rel.clone());
                }
            }
        }

        let _ = fs::remove_dir_all(&self.staging_dir);
        Ok(CommitReport {
            written,
            deleted,
            generated_hashes,
        })
    }

    /// Discard everything staged. The real output was never modified.
    pub fn abort(self) -> Result<(), TransactionError> {
        if self.staging_dir.exists() {
            fs::remove_dir_all(&self.staging_dir)?;
        }
        Ok(())
    }

    /// Number of changes that will be applied on commit.
    pub fn pending_changes(&self) -> usize {
        self.entries.len()
    }

    fn fail_untouched(&self, error: TransactionError) -> Result<CommitReport, TransactionError> {
        let _ = self.write_journal("failed", Some(&error.to_string()));
        Err(error)
    }

    fn apply_entry(
        &self,
        entry: &Entry,
        backup_root: &Path,
        applied: &mut Vec<Applied>,
    ) -> io::Result<()> {
        // Re-check confinement at the moment of the write.
        confine_path(&self.output_root, Path::new(&entry.rel))
            .map_err(|error| io::Error::new(io::ErrorKind::PermissionDenied, error.to_string()))?;

        let backup = if entry.observed.is_some() {
            let backup = backup_root.join(&entry.rel);
            if let Some(parent) = backup.parent() {
                fs::create_dir_all(parent)?;
            }
            fs::copy(&entry.target, &backup)?;
            Some(backup)
        } else {
            None
        };

        let mut created_dirs = Vec::new();
        if let Some(parent) = entry.target.parent() {
            let mut ancestor = parent;
            while !ancestor.exists() && ancestor.starts_with(&self.output_root) {
                created_dirs.push(ancestor.to_path_buf());
                match ancestor.parent() {
                    Some(next) => ancestor = next,
                    None => break,
                }
            }
        }

        // Recorded before the mutation so a failure partway is still undone.
        applied.push(Applied {
            target: entry.target.clone(),
            backup,
            created_dirs,
        });

        match &entry.action {
            Action::Write { staged, .. } => {
                if let Some(parent) = entry.target.parent() {
                    fs::create_dir_all(parent)?;
                }
                if fs::rename(staged, &entry.target).is_err() {
                    fs::copy(staged, &entry.target)?;
                }
            }
            Action::Delete => fs::remove_file(&entry.target)?,
        }
        Ok(())
    }

    /// Undo applied changes, newest first. Returns whether everything was restored.
    fn roll_back(applied: &[Applied]) -> bool {
        let mut complete = true;
        for change in applied.iter().rev() {
            match &change.backup {
                Some(backup) => {
                    if fs::copy(backup, &change.target).is_err() {
                        complete = false;
                    }
                }
                None => {
                    if fs::symlink_metadata(&change.target).is_ok()
                        && fs::remove_file(&change.target).is_err()
                    {
                        complete = false;
                    }
                }
            }
            for dir in &change.created_dirs {
                let _ = fs::remove_dir(dir);
            }
        }
        complete
    }

    fn build_candidate_tree(&self) -> io::Result<PathBuf> {
        let candidate = self.staging_dir.join("candidate");
        if candidate.exists() {
            fs::remove_dir_all(&candidate)?;
        }
        fs::create_dir_all(&candidate)?;

        if self.output_root.is_dir() {
            let walker = WalkDir::new(&self.output_root)
                .follow_links(false)
                .into_iter()
                .filter_entry(|entry| {
                    entry.depth() == 0
                        || !UNMANAGED_DIRS.contains(&entry.file_name().to_string_lossy().as_ref())
                });
            for entry in walker {
                let entry = entry.map_err(io::Error::other)?;
                let Ok(relative) = entry.path().strip_prefix(&self.output_root) else {
                    continue;
                };
                let destination = candidate.join(relative);
                if entry.file_type().is_dir() {
                    fs::create_dir_all(&destination)?;
                } else if entry.file_type().is_file() {
                    fs::copy(entry.path(), &destination)?;
                }
                // Symbolic links are deliberately not reproduced.
            }
        }

        for entry in &self.entries {
            let destination = candidate.join(&entry.rel);
            match &entry.action {
                Action::Write { staged, .. } => {
                    if let Some(parent) = destination.parent() {
                        fs::create_dir_all(parent)?;
                    }
                    fs::copy(staged, &destination)?;
                }
                Action::Delete => {
                    if destination.exists() {
                        fs::remove_file(&destination)?;
                    }
                }
            }
        }
        Ok(candidate)
    }

    /// `a/b/c` form of a confined target, refusing locations Sayn never manages.
    fn relative_name(&self, target: &Path, raw: &str) -> Result<String, TransactionError> {
        let unsafe_path = || TransactionError::UnsafePath(raw.to_string());
        let relative = target
            .strip_prefix(&self.output_root)
            .map_err(|_| unsafe_path())?;

        let mut parts = Vec::new();
        for component in relative.components() {
            let Component::Normal(part) = component else {
                return Err(unsafe_path());
            };
            let part = part.to_str().ok_or_else(unsafe_path)?;
            if UNMANAGED_DIRS.contains(&part) {
                return Err(unsafe_path());
            }
            parts.push(part);
        }
        let Some(file_name) = parts.last() else {
            return Err(unsafe_path());
        };
        // Real environment files hold secrets; only the example is generated.
        let lowered = file_name.to_lowercase();
        if lowered == ".env" || (lowered.starts_with(".env.") && lowered != ".env.example") {
            return Err(unsafe_path());
        }
        Ok(parts.join("/"))
    }

    fn manifest_key(&self, target: &Path, rel: &str) -> String {
        match target.strip_prefix(&self.project_root) {
            Ok(relative) => relative.to_string_lossy().replace('\\', "/"),
            Err(_) => rel.to_string(),
        }
    }

    fn write_journal(&self, state: &str, reason: Option<&str>) -> io::Result<()> {
        let journal = Journal {
            run_id: &self.run_id,
            state,
            updated_at: chrono::Utc::now().to_rfc3339(),
            reason,
            changes: self
                .entries
                .iter()
                .map(|entry| JournalChange {
                    path: &entry.rel,
                    action: match entry.action {
                        Action::Write { .. } => "write",
                        Action::Delete => "delete",
                    },
                })
                .collect(),
        };
        let content = serde_json::to_string_pretty(&journal).map_err(io::Error::other)?;
        fs::write(self.staging_dir.join("journal.json"), content)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    struct Project {
        _dir: tempfile::TempDir,
        root: PathBuf,
        output: PathBuf,
    }

    fn project() -> Project {
        let dir = tempdir().unwrap();
        let root = dir.path().to_path_buf();
        let output = root.join(".sayn/generated");
        fs::create_dir_all(&output).unwrap();
        Project {
            _dir: dir,
            root,
            output,
        }
    }

    fn write(path: &str, content: &str) -> StagedChange {
        StagedChange::Write {
            path: path.into(),
            content: content.as_bytes().to_vec(),
        }
    }

    fn delete(path: &str) -> StagedChange {
        StagedChange::Delete { path: path.into() }
    }

    /// Put a file in the output and record it in a manifest as generated.
    fn managed(project: &Project, manifest: &mut Manifest, rel: &str, content: &str) {
        let path = project.output.join(rel);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(&path, content).unwrap();
        manifest.generated_hashes.insert(
            format!(".sayn/generated/{rel}"),
            Manifest::compute_sha256(content.as_bytes()),
        );
    }

    fn begin(project: &Project, previous: Option<&Manifest>) -> GenerationTransaction {
        GenerationTransaction::begin(&project.root, &project.output, "run-1", previous).unwrap()
    }

    fn read(project: &Project, rel: &str) -> String {
        fs::read_to_string(project.output.join(rel)).unwrap()
    }

    #[test]
    fn commit_writes_new_files_and_reports_their_digests() {
        let project = project();
        let mut transaction = begin(&project, None);
        transaction
            .stage(&[write("app/page.tsx", "page"), write("package.json", "{}")])
            .unwrap();
        assert!(!project.output.join("app/page.tsx").exists());

        let report = transaction.commit().unwrap();

        assert_eq!(read(&project, "app/page.tsx"), "page");
        assert_eq!(report.written, vec!["app/page.tsx", "package.json"]);
        assert_eq!(
            report.generated_hashes[".sayn/generated/app/page.tsx"],
            Manifest::compute_sha256(b"page")
        );
        assert!(!GenerationTransaction::staging_dir_for(&project.root, "run-1").exists());
    }

    #[test]
    fn rejects_traversal_absolute_and_unmanaged_locations() {
        let project = project();
        for path in [
            "../outside.txt",
            "app/../../outside.txt",
            "/etc/passwd",
            "node_modules/pkg/index.js",
            ".git/config",
            ".env",
            ".env.local",
            "",
        ] {
            let mut transaction = begin(&project, None);
            let error = transaction.stage(&[write(path, "x")]).unwrap_err();
            assert!(
                matches!(error, TransactionError::UnsafePath(_)),
                "path {path:?} gave {error:?}"
            );
        }
        assert!(!project.root.join("outside.txt").exists());
    }

    #[cfg(unix)]
    #[test]
    fn rejects_writes_through_a_symlink_that_leaves_the_output() {
        let project = project();
        let outside = tempdir().unwrap();
        std::os::unix::fs::symlink(outside.path(), project.output.join("app")).unwrap();

        let mut transaction = begin(&project, None);
        let error = transaction
            .stage(&[write("app/page.tsx", "x")])
            .unwrap_err();

        assert!(matches!(error, TransactionError::UnsafePath(_)));
        assert!(!outside.path().join("page.tsx").exists());
    }

    #[test]
    fn rejects_duplicate_targets() {
        let project = project();
        let mut transaction = begin(&project, None);
        let error = transaction
            .stage(&[write("app/page.tsx", "a"), write("./App/page.tsx", "b")])
            .unwrap_err();
        assert!(matches!(error, TransactionError::DuplicateTarget(_)));
        assert_eq!(transaction.pending_changes(), 0);
    }

    #[test]
    fn manually_edited_file_is_a_conflict_and_is_left_alone() {
        let project = project();
        let mut manifest = Manifest::new("p", "1");
        managed(&project, &mut manifest, "app/page.tsx", "generated");
        managed(&project, &mut manifest, "app/layout.tsx", "layout");
        fs::write(project.output.join("app/page.tsx"), "my own edit").unwrap();

        let mut transaction = begin(&project, Some(&manifest));
        let error = transaction
            .stage(&[
                write("app/layout.tsx", "new layout"),
                write("app/page.tsx", "regenerated"),
            ])
            .unwrap_err();

        match error {
            TransactionError::ManualEditConflict { paths } => {
                assert_eq!(paths, vec!["app/page.tsx"]);
            }
            other => panic!("unexpected error: {other:?}"),
        }
        assert_eq!(read(&project, "app/page.tsx"), "my own edit");
        assert_eq!(read(&project, "app/layout.tsx"), "layout");
    }

    #[test]
    fn file_sayn_did_not_generate_is_not_overwritten() {
        let project = project();
        fs::write(project.output.join("notes.md"), "mine").unwrap();

        let mut transaction = begin(&project, None);
        let error = transaction
            .stage(&[write("notes.md", "theirs")])
            .unwrap_err();

        assert!(matches!(error, TransactionError::ManualEditConflict { .. }));
        assert_eq!(read(&project, "notes.md"), "mine");
    }

    #[test]
    fn unchanged_managed_file_can_be_replaced() {
        let project = project();
        let mut manifest = Manifest::new("p", "1");
        managed(&project, &mut manifest, "app/page.tsx", "old");

        let mut transaction = begin(&project, Some(&manifest));
        transaction.stage(&[write("app/page.tsx", "new")]).unwrap();
        transaction.commit().unwrap();

        assert_eq!(read(&project, "app/page.tsx"), "new");
    }

    #[test]
    fn deletion_requires_provenance() {
        let project = project();
        let mut manifest = Manifest::new("p", "1");
        managed(&project, &mut manifest, "app/old.tsx", "old");
        fs::write(project.output.join("keep.txt"), "user file").unwrap();

        let mut transaction = begin(&project, Some(&manifest));
        let error = transaction.stage(&[delete("keep.txt")]).unwrap_err();
        assert!(matches!(error, TransactionError::UnmanagedDelete(_)));
        assert!(project.output.join("keep.txt").exists());

        let mut transaction = begin(&project, Some(&manifest));
        let error = transaction.stage(&[delete("app")]).unwrap_err();
        assert!(matches!(error, TransactionError::NotAFile(_)));

        let mut transaction = begin(&project, Some(&manifest));
        transaction
            .stage(&[delete("app/old.tsx"), delete("app/never-existed.tsx")])
            .unwrap();
        let report = transaction.commit().unwrap();
        assert_eq!(report.deleted, vec!["app/old.tsx"]);
        assert!(!project.output.join("app/old.tsx").exists());
        assert!(
            !report
                .generated_hashes
                .contains_key(".sayn/generated/app/old.tsx")
        );
    }

    #[test]
    fn validation_sees_the_whole_candidate_and_failure_changes_nothing() {
        let project = project();
        let mut manifest = Manifest::new("p", "1");
        managed(&project, &mut manifest, "package.json", "{}");
        managed(&project, &mut manifest, "app/old.tsx", "old");
        fs::create_dir_all(project.output.join("node_modules/pkg")).unwrap();
        fs::write(project.output.join("node_modules/pkg/index.js"), "x").unwrap();

        let mut transaction = begin(&project, Some(&manifest));
        transaction
            .stage(&[write("app/page.tsx", "page"), delete("app/old.tsx")])
            .unwrap();

        transaction
            .validate(|candidate| {
                assert!(candidate.join("package.json").exists());
                assert!(candidate.join("app/page.tsx").exists());
                assert!(!candidate.join("app/old.tsx").exists());
                assert!(!candidate.join("node_modules").exists());
                Ok(())
            })
            .unwrap();

        let error = transaction
            .validate(|_| Err("build failed".into()))
            .unwrap_err();
        assert!(matches!(error, TransactionError::Validation(_)));
        transaction.abort().unwrap();

        assert!(!project.output.join("app/page.tsx").exists());
        assert_eq!(read(&project, "app/old.tsx"), "old");
        assert!(!GenerationTransaction::staging_dir_for(&project.root, "run-1").exists());
    }

    #[cfg(unix)]
    #[test]
    fn failure_partway_through_commit_restores_the_previous_output() {
        use std::os::unix::fs::PermissionsExt;

        let project = project();
        let mut manifest = Manifest::new("p", "1");
        managed(&project, &mut manifest, "app/page.tsx", "old page");
        managed(&project, &mut manifest, "app/gone.tsx", "to delete");
        let locked = project.output.join("locked");
        fs::create_dir(&locked).unwrap();

        let mut transaction = begin(&project, Some(&manifest));
        transaction
            .stage(&[
                write("app/page.tsx", "new page"),
                delete("app/gone.tsx"),
                write("fresh/dir/new.tsx", "new"),
                write("locked/file.tsx", "never lands"),
            ])
            .unwrap();
        // The last change can no longer be written, after three have applied.
        fs::set_permissions(&locked, fs::Permissions::from_mode(0o555)).unwrap();
        if fs::write(locked.join("probe"), "x").is_ok() {
            // Running with privileges that ignore directory permissions.
            fs::set_permissions(&locked, fs::Permissions::from_mode(0o755)).unwrap();
            return;
        }

        let error = transaction.commit().unwrap_err();
        fs::set_permissions(&locked, fs::Permissions::from_mode(0o755)).unwrap();

        match error {
            TransactionError::CommitFailed { rolled_back, .. } => assert!(rolled_back),
            other => panic!("unexpected error: {other:?}"),
        }
        assert_eq!(read(&project, "app/page.tsx"), "old page");
        assert_eq!(read(&project, "app/gone.tsx"), "to delete");
        assert!(!project.output.join("fresh").exists());
        assert!(!locked.join("file.tsx").exists());

        let journal = fs::read_to_string(
            GenerationTransaction::staging_dir_for(&project.root, "run-1").join("journal.json"),
        )
        .unwrap();
        assert!(journal.contains("rolled_back"));
    }

    #[test]
    fn directory_replaced_by_a_file_after_staging_blocks_the_commit() {
        let project = project();
        let mut transaction = begin(&project, None);
        transaction
            .stage(&[write("first.tsx", "one"), write("blocked/file.tsx", "two")])
            .unwrap();
        fs::write(project.output.join("blocked"), "in the way").unwrap();

        let error = transaction.commit().unwrap_err();

        assert!(matches!(error, TransactionError::ChangedDuringRun(_)));
        assert!(!project.output.join("first.tsx").exists());
        assert_eq!(read(&project, "blocked"), "in the way");
    }

    #[test]
    fn file_changed_after_staging_blocks_the_commit() {
        let project = project();
        let mut manifest = Manifest::new("p", "1");
        managed(&project, &mut manifest, "app/page.tsx", "old");

        let mut transaction = begin(&project, Some(&manifest));
        transaction
            .stage(&[
                write("app/page.tsx", "new"),
                write("app/other.tsx", "other"),
            ])
            .unwrap();
        fs::write(project.output.join("app/page.tsx"), "edited meanwhile").unwrap();

        let error = transaction.commit().unwrap_err();

        assert!(matches!(error, TransactionError::ChangedDuringRun(_)));
        assert_eq!(read(&project, "app/page.tsx"), "edited meanwhile");
        assert!(!project.output.join("app/other.tsx").exists());
    }

    #[test]
    fn rejects_run_ids_that_are_not_plain_names() {
        let project = project();
        for run_id in ["", "../x", "a/b", "a b"] {
            assert!(matches!(
                GenerationTransaction::begin(&project.root, &project.output, run_id, None),
                Err(TransactionError::InvalidRunId(_))
            ));
        }
    }
}
